test("expect", () => chaiExpect([1, 2]).to.have.lengthOf(2));
test("assert", () => { assert.equal(1, "1"); assert.strictEqual(2, 2); assert.deepEqual({ a: 1 }, { a: 1 }); assert.isTrue(true); assert.include("abc", "b"); });
